const menu=document.querySelector('#menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));nav.classList.toggle('open',!expanded)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#service').value=a.dataset.service}));
const form=document.querySelector('#request-form');window.FenekLeads.bind(form,()=>({service:form.querySelector('[name=service]').value,source:'payment_form',kind:'payment',amount:form.querySelector('[name=amount]').value,currency:'CNY',details:form.querySelector('[name=details]').value}));
const tabs=[...document.querySelectorAll('[data-tab]')],destination=document.querySelector('#exchange-destination');const modes={topup:{options:['Alipay','WeChat Pay'],label:'Куда зачислить',hint:'Сумма необязательна. Оставьте контакт — поможем с расчётом.'},supplier:{options:['Оплата поставщику','Оплата по QR-коду'],label:'Способ оплаты',hint:'Реквизиты, инвойс или QR-код можно отправить менеджеру после расчёта.'},buyout:{options:['1688','Taobao','Другой поставщик'],label:'Где покупаете',hint:'Пришлите ссылки и количество — согласуем стоимость выкупа и расходы.'}};function selectMode(key){tabs.forEach(t=>{const active=t.dataset.tab===key;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});const mode=modes[key];destination.replaceChildren(...mode.options.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;return o}));document.querySelector('label[for="exchange-destination"]').textContent=mode.label;document.querySelector('#exchange-hint').textContent=mode.hint;document.querySelector('#exchange-fields').setAttribute('aria-labelledby','tab-'+key);updateIcon()}function updateIcon(){const value=destination.value;const el=document.querySelector('#destination-icon');el.textContent=value==='Alipay'?'支':value==='WeChat Pay'?'微':value==='1688'?'1688':value==='Taobao'?'淘':'¥';el.dataset.type=value==='WeChat Pay'?'wechat':value==='1688'||value==='Taobao'?'market':'ali'}tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectMode(t.dataset.tab));t.addEventListener('keydown',e=>{let idx;if(e.key==='ArrowRight')idx=(i+1)%tabs.length;if(e.key==='ArrowLeft')idx=(i+tabs.length-1)%tabs.length;if(e.key==='Home')idx=0;if(e.key==='End')idx=tabs.length-1;if(idx!==undefined){e.preventDefault();selectMode(tabs[idx].dataset.tab);tabs[idx].focus()}})});destination.addEventListener('change',()=>{updateIcon();window.FenekAnalytics?.goal('exchange_select',{service:destination.value,page:location.pathname})});window.FenekLeads.bind(document.querySelector('#exchange-form'),()=>({service:destination.value,source:'exchange_form',kind:'payment',amount:document.querySelector('#exchange-amount').value,currency:document.querySelector('#exchange-currency').value,context:'Направление: '+destination.value}));
